'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var Float64Array = require( '@stdlib/array/float64' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var gnancount = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'generic', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gnancount, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( gnancount.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function counts the number of non-`NaN` elements in a one-dimensional ndarray', function test( t ) {
	var x;
	var v;

	x = [ 1.0, NaN, -2.0, NaN, 0.0, -0.0, Infinity, -Infinity ];
	v = gnancount( [ vector( x, x.length, 1, 0 ) ] );
	t.strictEqual( v, 6, 'returns expected value' );

	x = [ NaN, NaN ];
	v = gnancount( [ vector( x, x.length, 1, 0 ) ] );
	t.strictEqual( v, 0, 'returns expected value' );

	x = [ -4.0, 5.0 ];
	v = gnancount( [ vector( x, x.length, 1, 0 ) ] );
	t.strictEqual( v, 2, 'returns expected value' );

	t.end();
});

tape( 'if provided an empty ndarray, the function returns `0`', function test( t ) {
	var x;

	x = vector( [], 0, 1, 0 );
	t.strictEqual( gnancount( [ x ] ), 0, 'returns expected value' );

	x = vector( [ 1.0, 2.0 ], 0, 1, 1 );
	t.strictEqual( gnancount( [ x ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays containing a single element', function test( t ) {
	var x;

	x = vector( [ 1.0 ], 1, 1, 0 );
	t.strictEqual( gnancount( [ x ] ), 1, 'returns expected value' );

	x = vector( [ NaN ], 1, 1, 0 );
	t.strictEqual( gnancount( [ x ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-unit strides', function test( t ) {
	var x;

	x = [ 1.0, NaN, 2.0, NaN, 3.0, NaN, 4.0 ];
	t.strictEqual( gnancount( [ vector( x, 4, 2, 0 ) ] ), 4, 'returns expected value' );

	x = [ NaN, 1.0, NaN, 2.0, NaN, 3.0, NaN ];
	t.strictEqual( gnancount( [ vector( x, 4, 2, 0 ) ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having negative strides', function test( t ) {
	var x;

	x = [ NaN, 1.0, NaN, 2.0, NaN, 3.0, NaN ];
	t.strictEqual( gnancount( [ vector( x, 3, -2, 5 ) ] ), 3, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 4, -2, 6 ) ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-zero offsets', function test( t ) {
	var x;

	x = [ 42.0, NaN, 1.0, NaN, NaN, 99.0 ];
	t.strictEqual( gnancount( [ vector( x, 3, 1, 1 ) ] ), 1, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 2, 2, 1 ) ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having zero strides', function test( t ) {
	var x;

	x = [ NaN, 1.0 ];
	t.strictEqual( gnancount( [ vector( x, 5, 0, 1 ) ] ), 5, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 5, 0, 0 ) ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having typed array buffers', function test( t ) {
	var x;

	x = new Float64Array( [ NaN, 1.0, NaN, 2.0, NaN ] );
	x = new ndarray( 'float64', x, [ 2 ], [ 2 ], 1, 'row-major' );
	t.strictEqual( gnancount( [ x ] ), 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports one-dimensional ndarrays having accessor array buffers', function test( t ) {
	var x;

	x = toAccessorArray( [ NaN, 1.0, NaN, 2.0, NaN, 3.0, NaN ] );
	t.strictEqual( gnancount( [ vector( x, 7, 1, 0 ) ] ), 3, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 3, 2, 1 ) ] ), 3, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 3, -2, 5 ) ] ), 3, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 4, -2, 6 ) ] ), 0, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 5, 0, 1 ) ] ), 5, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 5, 0, 0 ) ] ), 0, 'returns expected value' );
	t.strictEqual( gnancount( [ vector( x, 0, 1, 0 ) ] ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an array-like object containing the input ndarray', function test( t ) {
	var arrays;

	arrays = {
		'0': vector( [ 1.0, NaN, 2.0 ], 3, 1, 0 ),
		'length': 1
	};
	t.strictEqual( gnancount( arrays ), 2, 'returns expected value' );
	t.end();
});
